<?php

declare(strict_types=1);

namespace Doctrine\ORM\Query\AST\Functions;

use Doctrine\DBAL\Platforms\AbstractPlatform;
use Doctrine\DBAL\Spatial\SpatialRelation;
use Doctrine\ORM\Query\Parser;

use function enum_exists;
use function method_exists;
use function sprintf;
use function strtoupper;

/** @internal */
final class SpatialFunctions
{
    /**
     * Fails if the installed version of DBAL does not generate the SQL of spatial functions, or of the function
     * generated by the given method of the platforms.
     */
    public static function assertSupported(Parser $parser, string $name, string|null $method = null): void
    {
        if (
            enum_exists(SpatialRelation::class)
            && ($method === null || method_exists(AbstractPlatform::class, $method))
        ) {
            return;
        }

        $parser->semanticalError(sprintf('%s() requires doctrine/dbal 4.6 or newer.', strtoupper($name)));
    }

    private function __construct()
    {
    }
}
